// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(address(this), amount);
        (bool okPay, ) = payable(address(c)).call{value: amount}("");
        assertTrue(okPay);
        // Rule: withdrawing more than the contract balance must revert.
        bool ok;
        try c.withdraw(amount + 1) { ok = true; } catch { ok = false; }
        assertFalse(ok, "over-balance withdrawal must revert");
    }
    receive() external payable {}
}
